-- Matrundan produktions-preflight
--
-- Körs skrivskyddat mot produktionsdatabasen efter migration och före
-- publicering. Alla rader ska returnera ok = true. Därefter ska PostgRESTs
-- schema-cache laddas om och en autentiserad läsning av en verklig grupp göras.

WITH checks(name, ok) AS (
  VALUES
    ('read_rpc_current:get_group_app_state_v5h', to_regprocedure('public.get_group_app_state_v5h(uuid)') IS NOT NULL),
    ('read_rpc_fallback:get_group_app_state_v5g', to_regprocedure('public.get_group_app_state_v5g(uuid)') IS NOT NULL),
    ('visit_rpc:create_visit_with_review_v2', to_regprocedure('public.create_visit_with_review_v2(uuid,uuid,date,text,uuid[],smallint,smallint,smallint,smallint,text,text[])') IS NOT NULL),
    ('visit_rpc:selected-members-only', COALESCE(position('COALESCE(_participant_ids' IN pg_get_functiondef(to_regprocedure('public.create_visit_with_review_v2(uuid,uuid,date,text,uuid[],smallint,smallint,smallint,smallint,text,text[])'))) > 0 AND position('ARRAY[_uid]' IN pg_get_functiondef(to_regprocedure('public.create_visit_with_review_v2(uuid,uuid,date,text,uuid[],smallint,smallint,smallint,smallint,text,text[])'))) = 0 AND position('has_membership(_group_id, participant.user_id)' IN pg_get_functiondef(to_regprocedure('public.create_visit_with_review_v2(uuid,uuid,date,text,uuid[],smallint,smallint,smallint,smallint,text,text[])'))) > 0, false)),
    ('visit_rpc:guest-privacy', COALESCE(position('WHEN visit_row.is_original THEN' IN pg_get_functiondef(to_regprocedure('public.get_group_app_state_v5h(uuid)'))) > 0 AND position('visit_row.guests' IN pg_get_functiondef(to_regprocedure('public.get_group_app_state_v5h(uuid)'))) > 0 AND position('ELSE visit_row.guest_count' IN pg_get_functiondef(to_regprocedure('public.get_group_app_state_v5h(uuid)'))) > 0, false)),
    ('settings_rpc:replace_group_search_settings', to_regprocedure('public.replace_group_search_settings(uuid,jsonb,integer)') IS NOT NULL),
    ('settings_helper:search_area_label_is_broad', to_regprocedure('public.search_area_label_is_broad(text)') IS NOT NULL),
    ('search-area:broad-label-guard', COALESCE(position('search_area_label_is_broad' IN pg_get_functiondef(to_regprocedure('public.replace_group_search_settings(uuid,jsonb,integer)'))) > 0 AND position('has_group_role' IN pg_get_functiondef(to_regprocedure('public.replace_group_search_settings(uuid,jsonb,integer)'))) > 0 AND position('group_is_active' IN pg_get_functiondef(to_regprocedure('public.replace_group_search_settings(uuid,jsonb,integer)'))) > 0, false)),
    ('storage:visit-photo-limit', EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'visit-photos' AND name = 'visit-photos' AND public = false AND file_size_limit = 1500000 AND allowed_mime_types = ARRAY['image/jpeg']::text[])),
    ('create_rpc:create_group_with_owner_v2', to_regprocedure('public.create_group_with_owner_v2(text,text,jsonb,integer)') IS NOT NULL),
    ('place_rpc:create_or_link_provider_place_v5f', to_regprocedure('public.create_or_link_provider_place_v5f(uuid,text,text,text,text,text[],text[],text,text,text,double precision,double precision,text,text,jsonb)') IS NOT NULL),
    ('place_rpc:create_or_link_provider_places_batch_v1', to_regprocedure('public.create_or_link_provider_places_batch_v1(uuid,jsonb)') IS NOT NULL),
    ('place_rpc:link_provider_source_to_existing_place_v1', to_regprocedure('public.link_provider_source_to_existing_place_v1(uuid,uuid,text,text,text,text,text,double precision,double precision,jsonb)') IS NOT NULL),
    ('place_rpc:get_external_info_context_v1', to_regprocedure('public.get_place_external_info_context_v1(uuid,uuid)') IS NOT NULL),
    ('place_rpc:get_external_info_context_membership', COALESCE(position('has_membership' IN pg_get_functiondef(to_regprocedure('public.get_place_external_info_context_v1(uuid,uuid)'))) > 0 AND position('provider = ''geoapify''' IN pg_get_functiondef(to_regprocedure('public.get_place_external_info_context_v1(uuid,uuid)'))) > 0 AND position('status = ''active''' IN pg_get_functiondef(to_regprocedure('public.get_place_external_info_context_v1(uuid,uuid)'))) > 0, false)),
    ('practical_info_rpc:update', to_regprocedure('public.update_group_place_practical_info_v1(uuid,uuid,text,jsonb,text,text)') IS NOT NULL),
    ('practical_info_rpc:get', to_regprocedure('public.get_group_place_practical_info_v1(uuid,uuid)') IS NOT NULL),
    ('practical_info_rpc:history', to_regprocedure('public.list_group_place_practical_info_history_v1(uuid,uuid,integer)') IS NOT NULL),
    ('practical_info_rpc:external-context-v2', to_regprocedure('public.get_place_external_info_context_v2(uuid,uuid)') IS NOT NULL),
    ('practical_info_rpc:save-snapshot', to_regprocedure('public.save_place_external_info_snapshot_v1(uuid,uuid,text,text,jsonb,text,timestamptz)') IS NOT NULL),
    ('practical_info_rpc:update-membership', COALESCE(position('has_membership' IN pg_get_functiondef(to_regprocedure('public.update_group_place_practical_info_v1(uuid,uuid,text,jsonb,text,text)'))) > 0 AND position('UPDATE public.group_places' IN pg_get_functiondef(to_regprocedure('public.update_group_place_practical_info_v1(uuid,uuid,text,jsonb,text,text)'))) > 0, false)),
    ('practical_info_rpc:snapshot-active-source', COALESCE(position('provider = ''geoapify''' IN pg_get_functiondef(to_regprocedure('public.save_place_external_info_snapshot_v1(uuid,uuid,text,text,jsonb,text,timestamptz)'))) > 0 AND position('status = ''active''' IN pg_get_functiondef(to_regprocedure('public.save_place_external_info_snapshot_v1(uuid,uuid,text,text,jsonb,text,timestamptz)'))) > 0 AND position('INSERT INTO public.place_external_info_snapshots' IN pg_get_functiondef(to_regprocedure('public.save_place_external_info_snapshot_v1(uuid,uuid,text,text,jsonb,text,timestamptz)'))) > 0, false)),
    ('cross_group_practical_info_rpc:get', to_regprocedure('public.get_cross_group_practical_info_suggestions_v1(uuid,uuid)') IS NOT NULL),
    ('cross_group_practical_info_rpc:apply', to_regprocedure('public.apply_cross_group_practical_info_suggestion_v1(uuid,uuid,text,text)') IS NOT NULL),
    ('cross_group_practical_info_rpc:privacy', COALESCE(position('gp.group_id <> _group_id' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) > 0 AND position('interval ''90 days''' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) > 0 AND position('''status'', ''conflicting''' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) > 0 AND position('sourceUrl' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) = 0 AND position('sourceNote' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) = 0 AND position('groupId' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) = 0 AND position('userId' IN pg_get_functiondef(to_regprocedure('public.cross_group_practical_info_candidate_v1(uuid,uuid,text)'))) = 0, false)),
    ('cross_group_practical_info_rpc:apply-revalidates', COALESCE(position('cross_group_practical_info_candidate_v1' IN pg_get_functiondef(to_regprocedure('public.apply_cross_group_practical_info_suggestion_v1(uuid,uuid,text,text)'))) > 0 AND position('fingerprint' IN pg_get_functiondef(to_regprocedure('public.apply_cross_group_practical_info_suggestion_v1(uuid,uuid,text,text)'))) > 0 AND position('group_place_practical_info_history' IN pg_get_functiondef(to_regprocedure('public.apply_cross_group_practical_info_suggestion_v1(uuid,uuid,text,text)'))) > 0, false)),
    ('place_trigger:resolve_missing_in_osm_reports', to_regprocedure('public.resolve_missing_in_osm_reports_for_active_source_v1()') IS NOT NULL),
    ('hidden_rpc:list', to_regprocedure('public.list_group_hidden_place_suggestions(uuid)') IS NOT NULL),
    ('hidden_rpc:list-v2', to_regprocedure('public.list_group_hidden_place_suggestions_v2(uuid)') IS NOT NULL),
    ('hidden_rpc:hide', to_regprocedure('public.hide_group_place_suggestion(uuid,text,text,text,text,text)') IS NOT NULL),
    ('hidden_rpc:hide-v2', to_regprocedure('public.hide_group_place_suggestion_v2(uuid,text,text,text,text,text,text,text,double precision,double precision,text)') IS NOT NULL),
    ('hidden_rpc:restore', to_regprocedure('public.restore_group_place_suggestion(uuid,text,text)') IS NOT NULL),
    ('place_data_report_rpc:create', to_regprocedure('public.create_place_data_report_v1(uuid,uuid,text,text)') IS NOT NULL),
    ('place_data_report_rpc:create-suggestion', to_regprocedure('public.create_place_data_report_from_suggestion_v1(uuid,text,text,text,text,text,text,double precision,double precision,text,text)') IS NOT NULL),
    ('place_data_report_rpc:list-v1', to_regprocedure('public.list_group_place_data_reports_v1(uuid)') IS NOT NULL),
    ('place_data_report_rpc:list-v2', to_regprocedure('public.list_group_place_data_reports_v2(uuid)') IS NOT NULL),
    ('place_data_report_rpc:list-v3', to_regprocedure('public.list_group_place_data_reports_v3(uuid)') IS NOT NULL),
    ('place_data_report_rpc:review', to_regprocedure('public.review_place_data_report_v1(uuid,uuid,text,text)') IS NOT NULL),
    ('place_data_report_rpc:suggestion-target-semantics', COALESCE(position('target_provider_place_id' IN pg_get_functiondef(to_regprocedure('public.create_place_data_report_from_suggestion_v1(uuid,text,text,text,text,text,text,double precision,double precision,text,text)'))) > 0 AND position('place_id' IN pg_get_functiondef(to_regprocedure('public.create_place_data_report_from_suggestion_v1(uuid,text,text,text,text,text,text,double precision,double precision,text,text)'))) > 0, false)),
    ('place_data_signal_rpc:get', to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)') IS NOT NULL),
    ('place_data_signal_rpc:confirm', to_regprocedure('public.confirm_place_data_signal_v1(uuid,uuid,text,text,text)') IS NOT NULL),
    ('place_data_signal_rpc:cross-group-only', COALESCE(position('report.group_id <> _group_id' IN pg_get_functiondef(to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)'))) > 0 AND position('confirmation.group_id <> _group_id' IN pg_get_functiondef(to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)'))) > 0, false)),
    ('place_data_signal_rpc:neutral-output', COALESCE(position('closureStatus' IN pg_get_functiondef(to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)'))) > 0 AND position('limitedInformation' IN pg_get_functiondef(to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)'))) > 0 AND position('recentlyConfirmedOpen' IN pg_get_functiondef(to_regprocedure('public.get_place_data_signals_v1(uuid,jsonb)'))) > 0, false)),
    ('osm_note_rpc:prepare', to_regprocedure('public.prepare_place_data_report_osm_submission_v1(uuid,uuid,text)') IS NOT NULL),
    ('osm_note_rpc:prepare-current-source-guard', COALESCE(position('Matstället har redan en aktiv OpenStreetMap-koppling' IN pg_get_functiondef(to_regprocedure('public.prepare_place_data_report_osm_submission_v1(uuid,uuid,text)'))) > 0, false)),
    ('osm_note_rpc:prepare-attempt-log-quota', COALESCE(position('place_data_report_osm_submission_attempts' IN pg_get_functiondef(to_regprocedure('public.prepare_place_data_report_osm_submission_v1(uuid,uuid,text)'))) > 0 AND position('osm-submit-user:' IN pg_get_functiondef(to_regprocedure('public.prepare_place_data_report_osm_submission_v1(uuid,uuid,text)'))) > 0 AND position('osm-submit-group:' IN pg_get_functiondef(to_regprocedure('public.prepare_place_data_report_osm_submission_v1(uuid,uuid,text)'))) > 0, false)),
    ('osm_note_rpc:complete', to_regprocedure('public.complete_place_data_report_osm_submission_v1(uuid,text,bigint,text,timestamptz,timestamptz,text)') IS NOT NULL),
    ('osm_note_rpc:fail', to_regprocedure('public.fail_place_data_report_osm_submission_v1(uuid,text,text)') IS NOT NULL),
    ('osm_note_rpc:get-refresh', to_regprocedure('public.get_place_data_report_osm_refresh_v1(uuid,uuid)') IS NOT NULL),
    ('osm_note_rpc:update-status', to_regprocedure('public.update_place_data_report_osm_status_v1(uuid,text,bigint,text,timestamptz)') IS NOT NULL),
    ('account_deletion:place_data_report_scrub', COALESCE(position('UPDATE public.place_data_reports' IN pg_get_functiondef(to_regprocedure('public.prepare_own_account_deletion(jsonb,boolean)'))) > 0 AND position('resolution_note = NULL' IN pg_get_functiondef(to_regprocedure('public.prepare_own_account_deletion(jsonb,boolean)'))) > 0, false)),
    ('account_deletion:osm_submitter_scrub', COALESCE(position('osm_submitted_by = NULL' IN pg_get_functiondef(to_regprocedure('public.prepare_own_account_deletion(jsonb,boolean)'))) > 0, false)),
    ('account_deletion:osm_attempt_submitter_scrub', COALESCE(position('place_data_report_osm_submission_attempts' IN pg_get_functiondef(to_regprocedure('public.prepare_own_account_deletion(jsonb,boolean)'))) > 0, false)),
    ('account_deletion:place_data_signal_delete', COALESCE(position('DELETE FROM public.place_data_signal_confirmations' IN pg_get_functiondef(to_regprocedure('public.prepare_own_account_deletion(jsonb,boolean)'))) > 0, false)),
    ('table:visit_guests', to_regclass('public.visit_guests') IS NOT NULL),
    ('table:group_search_areas', to_regclass('public.group_search_areas') IS NOT NULL),
    ('table:group_hidden_place_suggestions', to_regclass('public.group_hidden_place_suggestions') IS NOT NULL),
    ('table:place_data_reports', to_regclass('public.place_data_reports') IS NOT NULL),
