    ('table:place_external_info_snapshots', to_regclass('public.place_external_info_snapshots') IS NOT NULL),
    ('rls:visit_guests', COALESCE((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.visit_guests')), false)),
    ('rls:place_data_report_osm_submission_attempts', COALESCE((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.place_data_report_osm_submission_attempts')), false)),
    ('rls:place_data_signal_confirmations', COALESCE((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.place_data_signal_confirmations')), false)),
